# Spreadsheet analysis: evaluate formulas (SUM/AVG/refs) over a cell grid.
import re
cells = {'A1': 10, 'A2': 20, 'A3': '=SUM(A1:A2)'}
def val(addr, seen=None):
    seen = seen or set()
    if addr in seen: raise ValueError("circular ref " + addr)
    seen.add(addr)
    raw = cells[addr]
    if not isinstance(raw, str) or not raw.startswith("="):
        return raw
    expr = raw[1:]
    def rng(m):
        a, b = m.group(1), m.group(2)
        cols = [chr(c) for c in range(ord(a[0]), ord(b[0])+1)]
        return [c + str(r) for c in cols for r in range(int(a[1:]), int(b[1:])+1)]
    expr = re.sub(r"([A-Z]+\d+):([A-Z]+\d+)", lambda m: "[" + ",".join(rng(m)) + "]", expr)
    expr = re.sub(r"\bSUM\b", "sum", expr); expr = re.sub(r"\bAVG\b", "avg", expr)
    expr = re.sub(r"\b([A-Z]+\d+)\b", lambda m: repr(val(m.group(1), set(seen))), expr)
    avg = lambda xs: sum(xs)/len(xs)
    return eval(expr, {"__builtins__": {}}, {"sum": sum, "avg": avg})
for addr in sorted(cells):
    print(f"  {addr} = {cells[addr]!r:16} -> {val(addr)}")

